mapper.select:
SELECT
  (SELECT COALESCE(SUM(p.amount), 0)

     )                                   AS totalReceived,
  (SELECT COALESCE(SUM(p.amount), 0)

    WHERE p.paid_at >= DATE_FORMAT(CURDATE(), '%Y-%m-01')
      AND p.paid_at < DATE_ADD(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 1 MONTH)
      )                                    AS monthReceived,
  (SELECT COALESCE(SUM(p.amount), 0)

    WHERE p.paid_at >= DATE_ADD(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL -1 MONTH)
      AND p.paid_at < DATE_FORMAT(CURDATE(), '%Y-%m-01')
      )                                    AS lastMonthReceived,
  (SELECT COUNT(*)

     )                                   AS paymentCount,
  (SELECT COUNT(DISTINCT p.student_id)

     )                                   AS studentCount,
  (SELECT COUNT(*) FROM sales_order o

      AND o.campus_id = #{campusId}
    )                                                          AS orderCount,
  (SELECT COALESCE(SUM(o.debt), 0) FROM sales_order o

      AND o.campus_id = #{campusId}
    )                                                          AS debt
